package ch.bbw.zork;/* * author:  Michael Kolling, Version: 1.0, Date: July 1999 * refactoring: Rinaldo Lanza, September 2020 */import java.io.BufferedReader;import java.io.IOException;import java.io.InputStream;import java.io.InputStreamReader;import java.nio.charset.MalformedInputException;import java.util.InputMismatchException;public class Parser {    private static Parser instance;	private InputStream inputStream;	private Parser(InputStream inputStream) {		this.inputStream = inputStream;	}    public static Parser getInstance(InputStream inputStream) {        if (instance == null) {            instance = new Parser(System.in);        }        return instance;    }	public String[] getCommandInputs() {		BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));		try {			String inputLine = bufferedReader.readLine();			String[] tokens = inputLine.split(" ");			if (tokens.length > 2) {				throw new InputMismatchException("At most 1 Argument is expected.");			}			else if (!Zork2.validCommands.contains(tokens[0])) {				throw new IllegalArgumentException(String.format("'%s' is not a valid command!", tokens[0]));			}			return tokens;		} catch (Exception exc) {			System.out.println("There was an error during reading: " + exc.getMessage());		}		return null;	}	public boolean readYesNo(boolean def) throws IOException {		BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));		String inputLine = bufferedReader.readLine().toLowerCase();		switch (inputLine) {			case "y":				return true;			case "n":				return false;			case "":				return def;			default:				throw new InputMismatchException("Only n and y are valid inputs!");		}	}	public boolean readYesNo() throws IOException {		BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));		String inputLine = bufferedReader.readLine().toLowerCase();		switch (inputLine) {			case "y":				return true;			case "n":				return false;			default:				throw new InputMismatchException("Only n and y are valid inputs!");		}	}}